        if line.startswith(b'-'):
            try:
                orig = line.decode('utf-8')
            except:
                orig = line.decode('latin-1')
            # This is original - find the corresponding + line
            linenum = 0
            for i, l2 in enumerate(lines):
                if l2 == line:
                    linenum = i
                    break
            # Next line should be the + version
            if linenum + 1 < len(lines):
                plus_line = lines[linenum + 1]
                if plus_line.startswith(b'+'):
                    try:
                        new = plus_line.decode('utf-8')
                    except:
                        new = plus_line.decode('latin-1')
                    # Check if this has an emoji replacement
